size_t elf_vdso_coredump_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void elf_vdso_coredump_init(void) {
    g_ready = true;
    kprintf("[SYS/vDSO-ELF] Linux vDSO Syscall-Free Time Page + DT_GNU_HASH Linker + ELF64 Core-Dump (%lu rules)\n", (unsigned long)elf_vdso_coredump_db_size());
}

bool elf_vdso_coredump_selftest(void) {
    return g_ready && elf_vdso_coredump_db_size() >= 3520;
}
